import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.ktMMbWgA.js";const s="/intelligence-computed/lectures/L35-predictions/demo/figures/prediction_scorecard.png",n="/intelligence-computed/lectures/L35-predictions/demo/figures/critic_radar.png",b=JSON.parse('{"title":"第 35 讲 · 反派视角 + 六个预测 — 对一门技术最深的理解是能同时复述两面","description":"","frontmatter":{"title":"第 35 讲 · 反派视角 + 六个预测 — 对一门技术最深的理解是能同时复述两面","act":6,"kind":"notes","prev":{"text":"L34 · 安全、红队与可解释性","link":"/lectures/L34-safety/"},"next":false},"headers":[],"relativePath":"lectures/L35-predictions/index.md","filePath":"lectures/L35-predictions/index.md","lastUpdated":null}'),l={name:"lectures/L35-predictions/index.md"};function i(d,t,u,c,p,h){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="第-35-讲-·-反派视角-六个预测-—-对一门技术最深的理解是能同时复述两面" tabindex="-1">第 35 讲 · 反派视角 + 六个预测 — 对一门技术最深的理解是能同时复述两面 <a class="header-anchor" href="#第-35-讲-·-反派视角-六个预测-—-对一门技术最深的理解是能同时复述两面" aria-label="Permalink to &quot;第 35 讲 · 反派视角 + 六个预测 — 对一门技术最深的理解是能同时复述两面&quot;">​</a></h1><blockquote><p>我们花了 34 讲构建了从统计直觉到 Transformer 到 Agent 到安全的完整理解。但最聪明的反对者们说：这一切可能建立在错误的范式上。本讲不回避批评——<strong>把四位怀疑论者的核心论点最强钢人化（Steelman）地复述</strong>，然后用**六个可被日后验证的具体预测（五个技术维度 + 一个社会维度）**收束全课。最后，回到序章的 50 行代码——同样的代码，你现在看到的已经完全不同了。</p></blockquote><table tabindex="0"><thead><tr><th>前置知识</th><th>核心产出</th><th>建议用时</th></tr></thead><tbody><tr><td>全部 34 讲——本讲是全课终章</td><td>① 能钢人化复述四位怀疑论者的核心批判 ② 理解每个批判对应的技术缺陷 ③ 掌握六个带时间节点的可验证预测 ④ 回到 50 行代码完成课程闭环 ⑤ 形成自己对 AI 未来的独立判断</td><td>阅读约 55 分钟</td></tr></tbody></table><hr><h2 id="从上一讲到这一讲" tabindex="-1">从上一讲到这一讲 <a class="header-anchor" href="#从上一讲到这一讲" aria-label="Permalink to &quot;从上一讲到这一讲&quot;">​</a></h2><p>第 34 讲问：<strong>这一切可能都建立在错误的范式上？四位怀疑论者说你们高兴得太早了。</strong></p><p>34 讲下来，你建立了一套完整的世界观：统计学习是基础，归纳偏置带来效率，Transformer 用规模碎压了手工设计，Scaling Law 指引方向，对齐让模型听话，Agent 让模型行动，安全确保可控。</p><p>这套叙事很圆满。太圆满了。</p><p>科学进步的历史告诉我们，当一个范式（Paradigm）看起来&quot;什么都能解释&quot;的时候，恰恰是它最脆弱的时候。地心说也曾完美解释所有天体运行——通过不断添加本轮和均轮。当前的大语言模型范式会不会也是如此？</p><p>让我们严肃地听听四位最聪明的批评者怎么说。</p><div class="warning custom-block github-alert"><p class="custom-block-title">⚠️ 阅读前的层级提示：与 L20 的诚实对话</p><p>本讲即将听到 Marcus 等人说：&quot;<strong>AI 的 System 2 是假的</strong>&quot;。这听起来像是直接打脸 <a href="/intelligence-computed/lectures/L20-reasoning-models/">L20</a> ——L20 不是刚说&quot;o1/R1 让 AI 有了 System 2&quot;吗？</p><p>两讲不矛盾——它们在<strong>不同层级</strong>回答<strong>不同问题</strong>：</p><ul><li><strong>L20 是工程层论断</strong>：在可验证任务（数学、代码、形式化证明）上，CoT + RLVR + Test-Time Compute 让模型生成的推理链<strong>确实提升了正确率</strong>。这是可复现的、可被基准测试证伪的工程事实。</li><li><strong>L35 是认知 / 哲学层论断</strong>：可被验证的进步<strong>能否泛化到不可验证的开放推理</strong>？模型生成的推理链<strong>是否对应模型内部的真实计算路径</strong>？还是只是更精巧的事后合理化？</li></ul><p>Marcus / Chollet / LeCun 的批判<strong>不否认 L20 的工程事实</strong>，他们追问的是&quot;这套机制的结构是否够格叫&#39;真正的推理&#39;&quot;。本讲不强求答案，而把工程层与认知层的界线<strong>显式画清</strong>——让你自己判断&quot;我接受这是 System 2 到何种程度&quot;。</p></div><hr><h2 id="_1-gary-marcus-符号推理不可能从模式匹配中涌现" tabindex="-1">1. Gary Marcus：符号推理不可能从模式匹配中涌现 <a class="header-anchor" href="#_1-gary-marcus-符号推理不可能从模式匹配中涌现" aria-label="Permalink to &quot;1. Gary Marcus：符号推理不可能从模式匹配中涌现&quot;">​</a></h2><h3 id="_1-1-核心论点" tabindex="-1">1.1 核心论点 <a class="header-anchor" href="#_1-1-核心论点" aria-label="Permalink to &quot;1.1 核心论点&quot;">​</a></h3><p><strong>Gary Marcus</strong>（纽约大学教授，认知科学家）是当前 AI 范式最激烈、最持久的批评者<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>。他的核心论点：</p><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>Marcus 的核心批判：当前的深度学习（包括 LLM）本质上是高级模式匹配（Pattern Matching），而非真正的推理。符号推理能力——逻辑演绎、因果推断、组合性泛化——不可能从统计关联中&quot;涌现&quot;出来。你需要在架构中显式地构建它。</strong></p></div><p>Marcus 的证据：</p><ul><li>LLM 无法可靠地做多位数乘法——这是纯规则操作，不应该依赖训练数据中见过多少乘法例子</li><li>LLM 在&quot;不在训练分布中&quot;的推理问题上大幅退化——如果真的&quot;学会了推理&quot;，为什么推理能力和问题的形式高度相关？</li><li>LLM 的&quot;推理链&quot;可能只是模仿训练数据中推理链的模式，而非实际在推理</li></ul><h3 id="_1-2-钢人化" tabindex="-1">1.2 钢人化 <a class="header-anchor" href="#_1-2-钢人化" aria-label="Permalink to &quot;1.2 钢人化&quot;">​</a></h3><p>Marcus 最强的论点不是&quot;LLM 不好用&quot;（它显然好用），而是：</p><div class="tip custom-block github-alert"><p class="custom-block-title">钢人化要点</p><p>&quot;<strong>LLM 在 80% 的任务上表现出色，不能证明它掌握了这些任务背后的能力。</strong> 一个在 1000 万道数学题上训练的模型可能在第 1000 万零一道题上失败——因为它学到的是模式，不是规则。如果你的飞行控制系统 95% 的时间工作正常——那 5% 就是坠机。我们需要的是 100% 可靠的推理，而模式匹配天然无法提供这种可靠性。&quot;</p></div><h3 id="_1-3-反驳与开放问题" tabindex="-1">1.3 反驳与开放问题 <a class="header-anchor" href="#_1-3-反驳与开放问题" aria-label="Permalink to &quot;1.3 反驳与开放问题&quot;">​</a></h3><p>反驳：GPT-4 + CoT 在很多推理任务上已经逼近人类水平；o1/o3 等推理模型通过搜索 + 验证大幅提升了可靠性。</p><p>开放问题：<strong>&quot;涌现&quot;是真正的能力习得，还是更精密的模式匹配？</strong> 如果是后者，那么 Scaling 到 10 万亿参数也无法解决 Marcus 指出的问题——它只是让&quot;模式库&quot;更大，但本质没变。</p><blockquote><p>[!abstract] 呼应线 🔗 <strong>System 1/2 线</strong>（终极呼应）：L01 埋线——人类有 System 1（快速直觉）和 System 2（慢速推理）。L20 呼应——o1 / R1 / Claude Extended Thinking 通过推理时计算让 AI 在可验证任务上生成了&quot;System 2&quot;似的推理链。本讲终极呼应：<strong>Marcus 的核心批判恰恰在说&quot;AI 的 System 2 是假的&quot;——它看起来在推理，实际上只是更精致的模式匹配（System 1 伪装成 System 2）。</strong> 这条线的张力在终章达到最高点。</p></blockquote><hr><h2 id="_2-yann-lecun-自回归-llm-是死胡同" tabindex="-1">2. Yann LeCun：自回归 LLM 是死胡同 <a class="header-anchor" href="#_2-yann-lecun-自回归-llm-是死胡同" aria-label="Permalink to &quot;2. Yann LeCun：自回归 LLM 是死胡同&quot;">​</a></h2><h3 id="_2-1-核心论点" tabindex="-1">2.1 核心论点 <a class="header-anchor" href="#_2-1-核心论点" aria-label="Permalink to &quot;2.1 核心论点&quot;">​</a></h3><p><strong>Yann LeCun</strong>（图灵奖得主，Meta 首席 AI 科学家）不是 AI 的怀疑论者——他是&quot;当前路线&quot;的怀疑论者<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>。他的核心论点：</p><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>LeCun 的核心批判：自回归语言模型（Autoregressive LLM）是通向 AGI 的死胡同。原因：(1) 语言是思维的压缩表达，不是思维本身——在 token 空间中推理效率极低；(2) 自回归生成一旦犯错就不可回退——错误会指数级放大；(3) 真正的智能需要&quot;世界模型&quot;——一种在高维向量空间中规划和推理的能力，而非在离散 token 中逐个采样。</strong></p></div><p>LeCun 提出的替代方案：<strong>JEPA（Joint Embedding Predictive Architecture）</strong> ——模型不预测下一个 token，而是在<strong>表示空间</strong>中预测未来状态。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>自回归 LLM:   token₁ → token₂ → token₃ → ...  (离散, 单向, 不可回退)</span></span>
<span class="line"><span>JEPA/世界模型: state₁ → predict state₂ → 在表示空间中规划 → 选择最优动作</span></span></code></pre></div><h3 id="_2-2-钢人化" tabindex="-1">2.2 钢人化 <a class="header-anchor" href="#_2-2-钢人化" aria-label="Permalink to &quot;2.2 钢人化&quot;">​</a></h3><p>LeCun 最强的论点：</p><div class="tip custom-block github-alert"><p class="custom-block-title">钢人化要点</p><p>&quot;<strong>一个婴儿在出生后几个月内学会的物理直觉——物体永恒性、重力、因果——需要的数据量比 GPT-4 的全部训练数据少几十亿倍。</strong> 这证明当前 LLM 的学习效率极低。LLM 用了整个互联网的文本才学会的&#39;推理&#39;，婴儿只用了几千小时的感官体验就掌握了。我们缺少的不是更多数据或更大模型，而是一个根本不同的学习架构——一个能在向量空间中构建世界模型的架构。&quot;</p></div><blockquote><p>[!abstract] 呼应线 🔗 <strong>归纳偏置 vs 规模</strong>（终极呼应，Part 1）：LeCun 的世界模型本质上是在说——<strong>纯规模路线的尽头是一堵墙，你需要重新引入正确的归纳偏置</strong>（世界模型架构、向量空间推理、物理先验）才能突破。从 L12 CNN 的局部性偏置、到 L18 Transformer 去掉偏置靠规模、再到 L33 物理世界的偏置反击——这条张力线在 LeCun 的批判中达到终极对峙。</p></blockquote><h3 id="_2-3-反驳与开放问题" tabindex="-1">2.3 反驳与开放问题 <a class="header-anchor" href="#_2-3-反驳与开放问题" aria-label="Permalink to &quot;2.3 反驳与开放问题&quot;">​</a></h3><p>反驳：LLM 已经展示出某种程度的&quot;世界模型&quot;能力（Othello-GPT 内部形成了棋盘表示）；多模态 LLM 正在整合视觉、音频等非语言信息。</p><p>开放问题：<strong>JEPA 目前还没有比 LLM 更成功的实证——它是对的理论但缺乏工程证明，还是根本走不通？</strong></p><hr><h2 id="_3-francois-chollet-arc-基准证明-llm-无法泛化" tabindex="-1">3. François Chollet：ARC 基准证明 LLM 无法泛化 <a class="header-anchor" href="#_3-francois-chollet-arc-基准证明-llm-无法泛化" aria-label="Permalink to &quot;3. François Chollet：ARC 基准证明 LLM 无法泛化&quot;">​</a></h2><h3 id="_3-1-核心论点" tabindex="-1">3.1 核心论点 <a class="header-anchor" href="#_3-1-核心论点" aria-label="Permalink to &quot;3.1 核心论点&quot;">​</a></h3><p><strong>François Chollet</strong>（Keras 作者，Google 研究员）创建了 <strong>ARC（Abstraction and Reasoning Corpus，抽象与推理语料库）</strong> 基准<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup>，专门用来检验 AI 是否具备真正的泛化能力。</p><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>Chollet 的核心批判：智能 ≠ 技能。LLM 展示的是&quot;技能&quot;（在大量训练数据上做模式匹配的能力），而非&quot;智能&quot;（面对全新问题时的推理泛化能力）。ARC 每道题都是全新的、从未在训练集中出现过的——它测试的是&quot;你能否在极少的例子中发现规则并推广&quot;，而非&quot;你是否见过类似的题目&quot;。</strong></p></div><p>ARC 题目示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入:  ■□□    输出:  □□■</span></span>
<span class="line"><span>       □■□           □■□</span></span>
<span class="line"><span>       □□□           □□□</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入:  □□■    输出:  ■□□</span></span>
<span class="line"><span>       □□□           □□□</span></span>
<span class="line"><span>       □■□           □■□</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题:  ■□□    输出:  ???</span></span>
<span class="line"><span>       □□□</span></span>
<span class="line"><span>       □□■</span></span></code></pre></div><p>人类看几个例子就能发现规则（左右翻转），但 LLM 在 ARC 上的表现远低于普通人——即使是 GPT-4o。</p><h3 id="_3-2-钢人化" tabindex="-1">3.2 钢人化 <a class="header-anchor" href="#_3-2-钢人化" aria-label="Permalink to &quot;3.2 钢人化&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">钢人化要点</p><p>&quot;<strong>如果你在 100 万道数学题上训练一个模型，它在第 100 万零一道同类型题上表现好——这只证明了它记住了这类题的模式。真正的泛化是：给你三个例子，你就能推导出规则并应用到全新情境中。人类儿童天然具备这种能力。当前最大的 LLM 在这个能力上不如五岁小孩。如果你把&#39;在训练分布内表现好&#39;叫做智能，那搜索引擎也是智能的。</strong>&quot;</p></div><h3 id="_3-3-反驳与开放问题" tabindex="-1">3.3 反驳与开放问题 <a class="header-anchor" href="#_3-3-反驳与开放问题" aria-label="Permalink to &quot;3.3 反驳与开放问题&quot;">​</a></h3><p>反驳：ARC 的任务设计本身可能有偏向（偏向视觉空间推理，而非所有类型的推理）；2024 年 ARC Prize 竞赛中，结合程序合成与 LLM 的方案已经达到 ~55% 的正确率。</p><blockquote><p>[!abstract] 呼应线 🔗 <strong>归纳偏置 vs 规模</strong>（终极呼应，Part 2）：Chollet 的 ARC 是这条张力线的<strong>终极试金石</strong>——如果规模路线是对的，那么足够大的模型应该能解决 ARC；如果规模不够，就需要新的归纳偏置（如程序合成、符号推理模块）。截至 2025 年，纯 LLM 方案在 ARC 上仍然挣扎——但混合方案正在缩小差距。裁决尚未做出。</p></blockquote><hr><h2 id="_4-具身派-没有身体就没有理解" tabindex="-1">4. 具身派：没有身体就没有理解 <a class="header-anchor" href="#_4-具身派-没有身体就没有理解" aria-label="Permalink to &quot;4. 具身派：没有身体就没有理解&quot;">​</a></h2><h3 id="_4-1-核心论点" tabindex="-1">4.1 核心论点 <a class="header-anchor" href="#_4-1-核心论点" aria-label="Permalink to &quot;4.1 核心论点&quot;">​</a></h3><p>以 <strong>Rodney Brooks</strong>（iRobot 创始人、MIT 教授）和 <strong>Karl Friston</strong>（自由能原理提出者）为代表的具身智能（Embodied Intelligence）阵营认为：</p><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>具身派的核心批判：真正的理解需要与物理世界的交互——感知、行动、感受后果。一个只处理文本符号的系统，无论多大多强，都不可能真正&quot;理解&quot;什么是&quot;重&quot;、什么是&quot;热&quot;、什么是&quot;痛&quot;。它处理的只是这些概念的符号标签（Symbolic Label），而非概念本身。</strong></p></div><p>这与 L33 讨论的 Moravec 悖论直接呼应：高级推理容易，低级感觉运动难——而具身派认为<strong>低级感觉运动才是智能的根基</strong>。</p><h3 id="_4-2-钢人化" tabindex="-1">4.2 钢人化 <a class="header-anchor" href="#_4-2-钢人化" aria-label="Permalink to &quot;4.2 钢人化&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">钢人化要点</p><p>&quot;<strong>LLM 可以完美地描述如何骑自行车——力的平衡、重心调节、转向的反直觉原理——但它永远不会&#39;骑&#39;自行车。描述和理解之间的鸿沟，就是语言和身体之间的鸿沟。人类智能诞生于数亿年与物理世界的交互进化中——你不能指望跳过这数亿年的&#39;物理经验&#39;，只从文本中就获得等价的理解。</strong>&quot;</p></div><h3 id="_4-3-反驳与开放问题" tabindex="-1">4.3 反驳与开放问题 <a class="header-anchor" href="#_4-3-反驳与开放问题" aria-label="Permalink to &quot;4.3 反驳与开放问题&quot;">​</a></h3><p>反驳：盲人和聋人同样具有高级智能，证明并非所有感官模态都是智能的必要条件；多模态模型正在整合视觉、音频、触觉信号。</p><p>开放问题：<strong>&quot;理解&quot;到底需不需要&quot;身体&quot;？</strong> 这是一个古老的哲学问题（具身认知 vs 功能主义），AI 的发展可能最终给出实证答案。</p><hr><h2 id="_5-六个可验证的预测-2026-2030" tabindex="-1">5. 六个可验证的预测（2026-2030） <a class="header-anchor" href="#_5-六个可验证的预测-2026-2030" aria-label="Permalink to &quot;5. 六个可验证的预测（2026-2030）&quot;">​</a></h2><p><img src="`+s+'" alt="预测记分卡——2030 年回来对答案"></p><p><em>图：六个预测的综合记分卡（前五个为技术维度，第六个为社会维度），每个预测带明确时间节点和可验证指标。</em></p><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>对一门技术最诚实的展望，不是&quot;我觉得 AI 会很厉害&quot;或&quot;AI 要完蛋了&quot;这种不可证伪的空话，而是给出带明确时间节点、可被日后验证的具体预测。</strong> 以下六个预测——前五个在技术维度（AI 能做到什么），第六个在社会维度（人类制度能跟上吗）—2030 年我们回来对答案。</p><p><strong>每条预测均附四元组（数据集版本 | 评估指标 | 判定阈值 | 判定主体）</strong>——预防 2030 年验证时退化为&quot;定义之争&quot;。这个设计原则在哲学上是 <strong>Karl Popper 可证伪性（falsifiability）</strong>——&quot;AI 会很厉害&quot; 不可证伪 → 不是科学陈述；&quot;到 2028 年 ARC &gt; 80%&quot; 可证伪 → 是科学陈述。</p></div><h3 id="预测一-推理能力" tabindex="-1">预测一：推理能力 <a class="header-anchor" href="#预测一-推理能力" aria-label="Permalink to &quot;预测一：推理能力&quot;">​</a></h3><blockquote><p><strong>到 2028 年底，单一模型（不含外部搜索或工具调用）将在 ARC-AGI 公开测试集上达到 &gt;80% 正确率。</strong></p><table tabindex="0"><thead><tr><th>四元组</th><th>赋值</th></tr></thead><tbody><tr><td>数据集版本</td><td><strong>ARC-AGI-2 公开集</strong>（2025 发布；如后续出现 ARC-AGI-3 则以预测作出时的最新公开版为准）</td></tr><tr><td>评估指标</td><td><strong>pass@1</strong>（每题允许 1 次提交），不使用 self-consistency / 多采样</td></tr><tr><td>判定阈值</td><td>公开集整体准确率 ≥ 80%（600+ 题 × 0.8 = 480 题以上）</td></tr><tr><td>判定主体</td><td><strong>ARC Prize Foundation 官方 leaderboard</strong>（<a href="https://arcprize.org" target="_blank" rel="noreferrer">https://arcprize.org</a>）</td></tr></tbody></table><p>如果成真 → Chollet 低估了规模+架构创新的组合力量。 如果落空 → 模式匹配有天花板，需要新范式。</p></blockquote><h3 id="预测二-世界模型" tabindex="-1">预测二：世界模型 <a class="header-anchor" href="#预测二-世界模型" aria-label="Permalink to &quot;预测二：世界模型&quot;">​</a></h3><blockquote><p><strong>到 2029 年底，至少一个&quot;世界模型&quot;（在向量空间而非 token 空间中做规划）将在标准机器人操作基准上超过纯自回归方案。</strong></p><table tabindex="0"><thead><tr><th>四元组</th><th>赋值</th></tr></thead><tbody><tr><td>数据集版本</td><td><strong>LIBERO 或 RoboCasa（2024 发布）以及 2026–2028 间社区广泛采纳的后续版本</strong>（以预测验证时 SOTA 论文库使用最多的版本为准）</td></tr><tr><td>评估指标</td><td><strong>全评测集平均任务成功率</strong>（task success rate, 同一硬件 + 同一训练预算 ± 20%）</td></tr><tr><td>判定阈值</td><td>世界模型方案 ≥ 纯自回归方案 + 5 个百分点（统计显著 p&lt;0.05）</td></tr><tr><td>判定主体</td><td><strong>CoRL / RSS / NeurIPS 同行评审论文</strong>（非厂商官方博客）</td></tr></tbody></table><p>如果成真 → LeCun 的方向论是对的，JEPA 类架构有实际价值。 如果落空 → 自回归范式的生命力比 LeCun 预计的更强。</p></blockquote><h3 id="预测三-具身智能" tabindex="-1">预测三：具身智能 <a class="header-anchor" href="#预测三-具身智能" aria-label="Permalink to &quot;预测三：具身智能&quot;">​</a></h3><blockquote><p><strong>到 2030 年底，至少一款通用家庭机器人（能在预定的 20 项日常家务上达成成功率 &gt;90%）将以 &lt;$20,000 的售价商业化。</strong></p><table tabindex="0"><thead><tr><th>四元组</th><th>赋值</th></tr></thead><tbody><tr><td><strong>20 项任务清单</strong></td><td>叠衣物、装卸洗碗机、扫一个房间、插拔充电器、烤面包、取快递、打包垃圾、调节空调、清理台面、折叠床单、按口语指令找物、水果切块、遛狗、送快递下楼、照顾植物、换灯泡、敷茶冲咖啡、打开包装、收干净衣服、为客人拿饮料（完整清单见 <a href="/intelligence-computed/lectures/L35-predictions/demo/figures/prediction_3_tasks">demo/figures/prediction_3_tasks.md</a>，以预测作出时版本为准）</td></tr><tr><td>评估指标</td><td><strong>20 项任务在 100 个不同家庭环境中的平均成功率</strong> ≥ 90%（任务路线 5 分钟内完成为成功，用户零介入）</td></tr><tr><td>判定阈值</td><td>商业售价（含税、不含代补贴） &lt; $20,000，中美两地都需达到</td></tr><tr><td>判定主体</td><td><strong>Consumer Reports / Wirecutter 等独立评测机构</strong>的实测报告（非厂商自报）</td></tr></tbody></table><p>如果成真 → Sim-to-Real gap 被工程力量解决，具身智能从实验室走向家庭。 如果落空 → 物理世界的复杂性超出了当前技术路线的能力。</p></blockquote><h3 id="预测四-安全与可解释性" tabindex="-1">预测四：安全与可解释性 <a class="header-anchor" href="#预测四-安全与可解释性" aria-label="Permalink to &quot;预测四：安全与可解释性&quot;">​</a></h3><blockquote><p><strong>到 2028 年底，主流 LLM 将提供模型层面的&quot;置信度&quot;指标——对于每个输出，模型给出一个经过校准（Calibrated）的&quot;我有多确定&quot;分数。</strong></p><table tabindex="0"><thead><tr><th>四元组</th><th>赋值</th></tr></thead><tbody><tr><td>数据集版本</td><td><strong>MMLU + TriviaQA + HellaSwag 三者合集</strong>（面向事实型问答），及代表性生成型任务集</td></tr><tr><td>评估指标</td><td><strong>Expected Calibration Error (ECE)</strong> 使用 15-bin reliability diagram 计算</td></tr><tr><td>判定阈值</td><td>主流 LLM（OpenAI / Anthropic / Google / Meta / DeepSeek / Qwen 中至少 3 家）的官方 API 返回的 confidence 字段在以上集上 ECE &lt; 0.05</td></tr><tr><td>判定主体</td><td><strong>HELM (Stanford CRFM)</strong> 或同类独立评测平台公布的评测报告</td></tr></tbody></table><p>如果成真 → 幻觉问题虽未消除但被有效标注，用户可以知道什么时候该信模型。 如果落空 → 模型的&quot;不知道自己不知道&quot;是架构性缺陷，非工程可解。</p></blockquote><h3 id="预测五-范式转换" tabindex="-1">预测五：范式转换 <a class="header-anchor" href="#预测五-范式转换" aria-label="Permalink to &quot;预测五：范式转换&quot;">​</a></h3><blockquote><p><strong>到 2030 年底，自回归 Transformer 仍将是 AI 工业的主要架构——尽管可能有重要的补充模块（检索、符号推理、世界模型），但核心不会被替代。</strong></p><table tabindex="0"><thead><tr><th>四元组</th><th>赋值</th></tr></thead><tbody><tr><td>指标</td><td><strong>全球 Top-20 商业 LLM API（按调用量 / 营收加权）中使用起点为「decoder-only Transformer + (可选) Mixture-of-Experts」架构的比例</strong></td></tr><tr><td>判定阈值</td><td>上述比例 ≥ 70%（SSM/Mamba/JEPA/纯符号 等非 Transformer 架构合计不超过 30%）</td></tr><tr><td>数据源</td><td><strong>State of AI Report 2030 年度商业架构统计</strong>或同类独立报告</td></tr><tr><td>判定主体</td><td>外部分析师（State of AI Report / a16z / Stratechery 等）公开报告</td></tr></tbody></table><p>如果成真 → Marcus 和 LeCun 的批判是正确的诊断但开错了药方——补丁比重建更实际。 如果落空 → 2020 年代的 Transformer 确实像 2000 年代的翻盖手机——功能完备但即将被颠覆。</p></blockquote><h3 id="预测六-人类社会的适应-非技术维度" tabindex="-1">预测六：人类社会的适应（非技术维度） <a class="header-anchor" href="#预测六-人类社会的适应-非技术维度" aria-label="Permalink to &quot;预测六：人类社会的适应（非技术维度）&quot;">​</a></h3><blockquote><p><strong>前五个预测都在问&quot;AI 能做到什么&quot;，第六个预测问&quot;人类制度能跟上吗&quot;——到 2030 年底，全球至少 5 个主要经济体（中、美、欧盟、英、印度、日本中至少 5 个）将通过强制性的&quot;AI 高风险用途许可制度&quot;，覆盖至少 3 类用途（医疗诊断、教育评测、信用评分中至少 3 类）。</strong></p><table tabindex="0"><thead><tr><th>四元组</th><th>赋值</th></tr></thead><tbody><tr><td>指标</td><td><strong>强制性许可制度数量</strong> = 上述 6 个经济体中，已通过立法且 2030-12-31 之前正式生效的&quot;AI 高风险许可&quot;法律的国家数</td></tr><tr><td>判定阈值</td><td>≥ 5 个经济体 + 每个经济体覆盖的高风险类别 ≥ 3 类</td></tr><tr><td>数据源</td><td><strong>OECD AI Policy Observatory</strong> + <strong>Stanford AI Index Report 2031</strong>（覆盖前一年的法规快照）</td></tr><tr><td>判定主体</td><td>OECD / Stanford HAI / Brookings 等独立政策研究机构的年度报告</td></tr></tbody></table><p>如果成真 → &quot;技术创新跑得过制度建设&quot;的悲观叙事被证伪——人类社会有能力建立起与 AI 能力相匹配的治理框架。EU AI Act (<a href="/intelligence-computed/lectures/L34-safety/">L34 §5.1.1</a>) 不是孤例，而是范本。 如果落空 → 治理与能力的差距进一步拉大，AI 应用的合规复杂度会成为下一个十年最大的工程瓶颈（远超技术挑战）。</p><div class="note custom-block github-alert"><p class="custom-block-title">为什么把它列成预测六</p><p>前五个预测都在 AI 系统<strong>内部</strong>——能不能推理、有没有世界模型、能不能造身体、安不安全、用什么架构。第六个预测在 AI 系统<strong>外部</strong>——人类制度怎么应对。</p><p><strong>如果你的工作是开发 AI 应用</strong>：第六个预测决定了你 2028-2030 年要面对的合规成本。EU AI Act 已经把高风险应用合规变成了显性的工程约束（参见 L34），如果还有 5 个经济体跟进 → 全球部署一个高风险 AI 应用 = 处理 5 套独立的合规框架 + 5 套独立的评估报告 + 5 套独立的责任界定。</p><p><strong>如果你的工作不直接接触 AI</strong>：这条预测决定了 AI 是被以&quot;互联网式扩散&quot;（监管落后于扩散）还是&quot;航空式扩散&quot;（监管和扩散同步）的方式融入社会。两条路径对就业、教育、医疗、司法的影响完全不同。</p></div></blockquote><div class="warning custom-block github-alert"><p class="custom-block-title">预测的价值</p><p>这些预测可能全错。但给出预测本身就有价值——它迫使你把模糊的直觉转化为具体的判断，而具体的判断可以被检验。<strong>这里加上了四元组（数据集版本 | 指标 | 阈值 | 判定主体）的原因是防止 2030 年验证时退化为&quot;定义之争&quot;</strong>——预测的价值不在于判断是否成真，而在于预先明确&quot;怎么算成真&quot;。</p><p><strong>六个预测的覆盖结构</strong>：</p><ul><li>预测一-二：AI <strong>能力</strong>边界（推理、世界模型）</li><li>预测三：AI <strong>物理形态</strong>（具身）</li><li>预测四：AI <strong>可控性</strong>（校准）</li><li>预测五：AI <strong>架构选择</strong>（Transformer 续命）</li><li>预测六：<strong>人类社会</strong>的适应能力</li></ul><p>这六个维度是 2030 年回头评判&quot;我们走到哪一步了&quot;的最少必要拼图。如果只看技术指标（前五个），可能 5/5 全对，但社会层面（第六个）仍然失败 —— 那就回到 <a href="/intelligence-computed/lectures/L01-cognitive-biases/">L01</a> 埋下的&quot;两次 AI 寒冬&quot;逻辑：技术能力的进步不能自动兑现为社会价值。</p></div><h2 id="_6-课程闭环-回到-50-行代码" tabindex="-1">6. 课程闭环：回到 50 行代码 <a class="header-anchor" href="#_6-课程闭环-回到-50-行代码" aria-label="Permalink to &quot;6. 课程闭环：回到 50 行代码&quot;">​</a></h2><p>回到第 1 讲的 50 行 Shakespeare 代码——<code>L00-prologue/demo/shakespeare_50lines_torch.py</code>。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 同样的代码。但你现在看到的完全不同了。</span></span></code></pre></div><p>第 1 讲你看到的是：一个&quot;神奇的&quot;程序——喂进去莎士比亚文本，输出了看起来像莎士比亚的东西。</p><p>34 讲后你看到的是：</p><ul><li><strong>L02</strong>：一个把交叉熵损失最小化的优化问题</li><li><strong>L05</strong>：一个 RNN 在序列上展开的自回归过程</li><li><strong>L06</strong>：字符被映射到向量空间，相似字符距离更近</li><li><strong>L07</strong>：如果把 RNN 换成 Transformer + 把字符换成 BPE token → GPT</li><li><strong>L09</strong>：如果把模型放大 10 万倍、数据放大 100 万倍 → GPT-4</li><li><strong>L12</strong>：如果再做 RLHF → ChatGPT</li><li><strong>L15-L22</strong>：如果再加 prompt engineering + tools + agent → AI 应用</li><li><strong>L28</strong>：但我们仍然不完全理解它内部在做什么</li><li><strong>★ L35</strong>：4 钢人化 + 6 预测——同时复述两面，你自己判断</li></ul><blockquote><p>[!abstract] ★★ 全课程 4 主线终极收官（对应 <a href="./slides_outline">slides_outline.md</a> §S62）</p><p>35 讲累积的 4 主线在本讲完成最浓缩的对峙——让&quot;对一门技术最深的理解是能同时复述两面&quot;在认知层完成：</p><table tabindex="0"><thead><tr><th>主线</th><th>起点</th><th>★★ L35 终极收官</th></tr></thead><tbody><tr><td><strong>System 1/2 主线</strong></td><td>L01 人类双系统</td><td>Marcus 认知层质疑——System 2 是假的（System 1 伪装）§1 · §S10</td></tr><tr><td><strong>归纳偏置 vs 规模主线</strong></td><td>L06 CNN 局部偏置</td><td>LeCun + Chollet 双重对峙——纯规模路线尽头是墙§2 + §3 · §S16 + §S24</td></tr><tr><td><strong>物理账单线（L33-L35）</strong></td><td>L33 Moravec + S2R</td><td>具身派终极呼应——Symbol Grounding Problem§4 · §S30</td></tr><tr><td><strong>Evaluator 线（L02-L34）</strong></td><td>L02 损失函数</td><td>L35 6 预测 = 延迟 Evaluator（2030 年验证）§5</td></tr></tbody></table></blockquote><div class="note custom-block github-alert"><p class="custom-block-title">终章之问</p><p><strong>&quot;它理解莎士比亚吗？&quot;</strong> 这是第 1 讲留下的问题。34 讲后，你的回答不应该是&quot;是&quot;或&quot;否&quot;——而应该是&quot;&#39;理解&#39;这个词在这个语境下意味着什么？按照什么定义？用什么标准衡量？&quot; 这门课教给你的不是一个答案，而是<strong>问出正确问题的能力</strong>。</p></div><hr><h2 id="失败模式-反例" tabindex="-1">失败模式 / 反例 <a class="header-anchor" href="#失败模式-反例" aria-label="Permalink to &quot;失败模式 / 反例&quot;">​</a></h2><blockquote><p>本节列出本讲核心结论<strong>不适用</strong>或<strong>易被误用</strong>的常见情境。教学的目的不是制造「已学会」的错觉，而是认清边界。</p></blockquote><ul><li>预测的「事后偏差」：所有「AI 预测史」回顾文章只引用对的预测；KurzWeil 等「预测大师」实际命中率 ~50%（与抛硬币持平）——选择性引用是教学陷阱。</li><li>「指数曲线必然延续」迷思：Moore 定律放缓、Kaplan 被 Chinchilla 推翻、Sora 一年未根本进步——「AI 加速」叙事需要保持怀疑。</li><li>短期高估、长期低估（Amara 定律）：本课程最稳的预测就是这一条——具体技术常被高估时间表，但底层影响常被低估。</li><li>自我应验 vs 自我证伪：广为流传的预测会改变行为（投资涌入、人才流动），从而<strong>改变它的概率</strong>——这让「客观预测」在 AI 领域接近不可能。</li></ul><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><ol><li><strong>Gary Marcus 指出了模式匹配的天花板</strong>——符号推理不可能从统计关联中涌现，LLM 的&quot;推理&quot;可能只是更精致的模式匹配。System 1 在伪装 System 2。</li><li><strong>Yann LeCun 认为自回归是死胡同</strong>——真正的智能需要在向量空间中构建世界模型做规划，而非在 token 空间中逐个采样。数据效率是当前范式的致命弱点。</li><li><strong>François Chollet 用 ARC 证明 LLM 无法真正泛化</strong>——智能 ≠ 技能，面对全新问题时的推理泛化能力才是智能的本质。</li><li><strong>具身派认为没有身体就没有理解</strong>——处理符号标签不等于理解概念，数亿年的物理交互经验不可能被文本替代。</li><li><strong>六个预测把模糊直觉转化为可验证判断</strong>——五个技术维度（推理能力 ARC &gt; 80%? / 世界模型 / 家庭机器人 / 校准置信度 / 范式持续性）+ 一个社会维度（高风险许可制度的全球落地）。2030 年对答案。</li></ol><p><img src="'+n+`" alt="四位怀疑论者的批判雷达图"></p><p><em>图：四位怀疑论者的批判维度对比——Marcus 关注组合泛化，LeCun 关注世界模型，Chollet 关注推理泛化，具身派关注物理交互。</em></p><hr><h2 id="动手环节" tabindex="-1">动手环节 <a class="header-anchor" href="#动手环节" aria-label="Permalink to &quot;动手环节&quot;">​</a></h2><blockquote><p>[!example] 动手 生成六个预测的可视化记分卡和批判者雷达图：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lectures/L35-predictions/demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prediction_scorecard.py</span></span></code></pre></div><p>完整代码见 <a href="/intelligence-computed/lectures/L35-predictions/demo/prediction_scorecard.py"><code>demo/prediction_scorecard.py</code></a>。</p></blockquote><hr><h2 id="📺-推荐视频" tabindex="-1">📺 推荐视频 <a class="header-anchor" href="#📺-推荐视频" aria-label="Permalink to &quot;📺 推荐视频&quot;">​</a></h2><ol><li>🎥 <strong><a href="https://www.youtube.com/watch?v=5t1vTLU7s40" target="_blank" rel="noreferrer">Lex Fridman — Yann LeCun: Meta AI, Open Source, Limits of LLMs</a></strong> — LeCun 对自回归范式的批判和 JEPA 替代方案。</li><li>🎥 <strong><a href="https://www.youtube.com/watch?v=PUAdj3w3wO4" target="_blank" rel="noreferrer">Lex Fridman — François Chollet: Measures of Intelligence</a></strong> — Chollet 对“什么是智能”的深度讨论。</li><li>🎥 <strong><a href="https://www.youtube.com/watch?v=VwhKGMIB4Yc" target="_blank" rel="noreferrer">Gary Marcus vs Yann LeCun — AI Debate</a></strong> — 两位怀疑论者的直接辩论，观点碰撞精彩。</li></ol><h2 id="🔗-互动资源" tabindex="-1">🔗 互动资源 <a class="header-anchor" href="#🔗-互动资源" aria-label="Permalink to &quot;🔗 互动资源&quot;">​</a></h2><ol><li>🌐 <strong><a href="https://ourworldindata.org/artificial-intelligence" target="_blank" rel="noreferrer">Our World in Data — Artificial Intelligence</a></strong> — AI 能力进展的权威数据可视化。</li><li>🌐 <strong><a href="https://epochai.org/trends" target="_blank" rel="noreferrer">Epoch AI — Trends in Machine Learning</a></strong> — 算力、数据、参数量趋势的权威数据源。</li><li>🌐 <strong><a href="https://arcprize.org/" target="_blank" rel="noreferrer">ARC Prize — ARC-AGI Benchmark</a></strong> — Chollet 提出的 ARC 基准，可在线查看当前最佳成绩。</li></ol><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ol><li>📕 <strong>Marcus, G. (2020). <em>The Next Decade in AI: Four Steps Towards Robust Artificial Intelligence</em></strong> — Marcus 对当前 AI 范式最系统的批判和替代路线图<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup>。</li><li>📄 <strong>LeCun, Y. (2022). &quot;A Path Towards Autonomous Machine Intelligence&quot;</strong> — LeCun 的世界模型与 JEPA 架构蓝图，提出了自回归之外的替代范式<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2:1]</a></sup>。</li><li>📄 <strong>Chollet, F. (2019). &quot;On the Measure of Intelligence&quot;</strong> — 对&quot;什么是智能&quot;的严格定义，以及 ARC 基准的设计哲学<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3:1]</a></sup>。</li><li>📝 <strong><a href="https://nautil.us/deep-learning-is-hitting-a-wall-238440/" target="_blank" rel="noreferrer">Gary Marcus: Deep Learning is Hitting a Wall</a></strong> — Marcus 面向大众的批判综述，文笔犀利、论点清晰。</li></ol><hr><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Marcus, G. (2020). &quot;The Next Decade in AI: Four Steps Towards Robust Artificial Intelligence&quot;. <a href="https://arxiv.org/abs/2002.06177" target="_blank" rel="noreferrer">arxiv:2002.06177</a> <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>LeCun, Y. (2022). &quot;A Path Towards Autonomous Machine Intelligence&quot;. <a href="https://openreview.net/pdf?id=BZ5a1r-kVsf" target="_blank" rel="noreferrer">openreview.net/pdf?id=BZ5a1r-kVsf</a> <a href="#fnref2" class="footnote-backref">↩︎</a> <a href="#fnref2:1" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p>Chollet, F. (2019). &quot;On the Measure of Intelligence&quot;. <a href="https://arxiv.org/abs/1911.01547" target="_blank" rel="noreferrer">arxiv:1911.01547</a> <a href="#fnref3" class="footnote-backref">↩︎</a> <a href="#fnref3:1" class="footnote-backref">↩︎</a></p></li></ol></section>`,112)])])}const q=o(l,[["render",i]]);export{b as __pageData,q as default};
